/**
 * The published sample deliverables (public/reference/*.html), as a visitor meets them.
 *
 * The documents are generated by scripts/build-reference.sh and are the canonical sample of what is sold. This file holds them to what
 * the site promises about them: the Density Screen sample exists and is the screening document a buyer receives (not the Study
 * re-skinned); every document is marked synthetic; none makes a request to a third party; none is a dead end; they are in the sitemap,
 * llms.txt and on /reference; and each head fits a search result.
 *
 * These read generated files, so they need `bash scripts/build-reference.sh` to have been run on the tree (CI's `reference` job and the
 * release regenerate it). The byte-for-byte drift guard is CI's; this is the shape.
 */
import fs from "node:fs";
import path from "node:path";
import React from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, it } from "vitest";
import { GET as llms } from "@/app/llms.txt/route";
import sitemap from "@/app/sitemap";
import { REFERENCE_DOCUMENTS, referencePath } from "@/lib/reference-docs";
import { PRODUCT_PAGES } from "@/lib/product-pages";
import { SITE_URL } from "@/lib/site";

const ROOT = process.cwd();
const REF = path.join(ROOT, "public", "reference");
const read = (f: string) => fs.readFileSync(path.join(REF, f), "utf8");
const head = (name: string) => {
  const h = read(`${name}.html`);
  return h.slice(0, h.indexOf("</head>"));
};

describe("the list of sample documents is the directory", () => {
  it("names every HTML page in public/reference, and no page that is not there", () => {
    const onDisk = fs.readdirSync(REF).filter((f) => f.endsWith(".html")).map((f) => f.replace(/\.html$/, "")).sort();
    expect([...REFERENCE_DOCUMENTS].sort()).toEqual(onDisk);
  });
});

describe("the Density Screen sample is the buyer's document", () => {
  const md = read("density_screen.md");
  const html = read("density_screen.html");

  it("exists in both formats the buyer receives, and in no format the buyer does not (the catalogue promises HTML and Markdown)", () => {
    expect(fs.existsSync(path.join(REF, "density_screen.json"))).toBe(false);
    expect(md.length).toBeGreaterThan(5_000);
    expect(html.length).toBeGreaterThan(20_000);
  });

  it("is a Density Screen, not the Study: the screening document's title and sections, with the screening stamp the buyer's copy carries", () => {
    expect(md).toMatch(/^# Density Screen — /);
    for (const section of ["1. The answer", "2. What stops this hall, in order", "3. Architectures screened", "What we had to assume", "Recommended next step"]) {
      expect(md, section).toContain(section);
    }
    expect(md).toContain("SCREENING OPINION");
    expect(md).not.toMatch(/^# .*Envelope Study/m);
    expect(html).toContain("<title>");
  });

  it("is marked as synthetic reference data, in both formats, above the screening stamp", () => {
    for (const t of [md, html]) {
      const synthetic = t.indexOf("SYNTHETIC REFERENCE DATA — NOT A CUSTOMER ASSET");
      const screening = t.indexOf("SCREENING OPINION");
      expect(synthetic).toBeGreaterThan(-1);
      expect(synthetic).toBeLessThan(screening);
    }
  });

  it("claims no result, customer or guarantee (the evidence-class table's own wording, 'validated against test data', is the engine's definition of E4)", () => {
    for (const t of [md, html]) expect(t.toLowerCase()).not.toMatch(/\b(proven|guaranteed|case study)\b/);
  });
});

describe.each([...REFERENCE_DOCUMENTS])("%s.html is a page of the site", (name) => {
  const html = read(`${name}.html`);

  it("requests nothing from a third party: no Google Fonts, no stylesheet or script by URL, no remote image", () => {
    expect(html).not.toMatch(/fonts\.(googleapis|gstatic)\.com/);
    expect(html).not.toMatch(/IBM Plex/);
    expect(html).not.toMatch(/<link[^>]+rel=['"]stylesheet['"]/);
    expect(html).not.toMatch(/<script[^>]+src=/i);
    expect(html).not.toMatch(/<img[^>]+src=['"]https?:/i);
    expect(html).not.toMatch(/@import|url\(\s*['"]?https?:/);
    const urls = [...html.matchAll(/https?:\/\/[^\s'"<>)]+/g)].map((m) => m[0]);
    // The only absolute URL is the page naming itself canonical.
    expect(urls.filter((u) => u !== `${SITE_URL}/reference/${name}.html`)).toEqual([]);
  });

  it("serves its fonts from the site (same files as the app) and declares them", () => {
    expect(html).toContain("@font-face");
    for (const f of fs.readdirSync(REF + "/fonts")) {
      expect(fs.readFileSync(path.join(REF, "fonts", f)).equals(fs.readFileSync(path.join(ROOT, "app", "fonts", f))), f).toBe(true);
    }
    for (const m of html.matchAll(/url\((fonts\/[a-z0-9-]+\.woff2)\)/g)) expect(fs.existsSync(path.join(REF, m[1])), m[1]).toBe(true);
  });

  it("is not a dead end: a way back to the sample deliverables, the free check, and the product it is a sample of", () => {
    const bar = /<nav class='gf-bar'[^>]*>([\s\S]*?)<\/nav>/.exec(html)?.[1] ?? "";
    expect(bar).toContain("Back to the sample deliverables");
    expect(bar).toContain("href='/reference'");
    expect(bar).toContain("href='/qualify'");
    expect(bar).toContain("Synthetic reference data");
    const next = /<a class='gf-cta' href='([^']+)'>/.exec(bar)?.[1];
    expect(PRODUCT_PAGES.map((p) => `/products/${p.slug}`)).toContain(next);
    // The bar is part of the page and hidden when the document is printed.
    expect(html).toContain("@media print{.gf-bar{display:none}}");
  });

  it("has exactly one main landmark, after the site bar", () => {
    expect((html.match(/<main>/g) ?? []).length).toBe(1);
    expect(html.indexOf("<main>")).toBeGreaterThan(html.indexOf("</nav>"));
    expect(html.indexOf("</main>")).toBeLessThan(html.indexOf("</body>"));
  });

  it("has a title and a description that fit a search result, and says its data is synthetic", () => {
    const title = /<title>([^<]*)<\/title>/.exec(head(name))?.[1] ?? "";
    const desc = /<meta name='description' content='([^']*)'>/.exec(head(name))?.[1] ?? "";
    expect(title.length).toBeGreaterThan(10);
    expect(title.length).toBeLessThanOrEqual(60);
    expect(desc.length).toBeLessThanOrEqual(160);
    expect(desc).toMatch(/Synthetic reference hall/);
    expect(head(name)).toMatch(/<html lang='en'>/);
  });
});

describe("the documents are findable", () => {
  it("every document is in the sitemap at its canonical URL", async () => {
    const urls = (await sitemap()).map((u) => u.url);
    for (const name of REFERENCE_DOCUMENTS) expect(urls, name).toContain(`${SITE_URL}${referencePath(name)}`);
  });

  it("llms.txt lists the Density Screen sample first among the published documents", async () => {
    const t = await (await llms()).text();
    const block = t.slice(t.indexOf("## The complete worked deliverable, published"));
    expect(block).toContain("/reference/density_screen.md");
    expect(block.indexOf("density_screen.md")).toBeLessThan(block.indexOf("envelope_study.md"));
  });

  it("/reference leads with the Density Screen and labels the Envelope Study as the next step", async () => {
    const page = (await import("@/app/reference/page")).default;
    const html = renderToStaticMarkup(await page()).replace(/<!-- -->/g, "");
    expect(html).toContain('href="/reference/density_screen.html"');
    expect(html.indexOf("/reference/density_screen.html")).toBeLessThan(html.indexOf("/reference/envelope_study.html"));
    expect(html).toMatch(/The next step: the Envelope Study/);
    expect(html).toContain('href="/products/density-screen"');
    expect(html).toContain('href="/products/envelope-study"');
    // The documents carry their own way back, so they open in the same tab.
    expect(html).not.toMatch(/target="_blank"/);
    const ld = [...html.matchAll(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g)].map((m) => JSON.parse(m[1]));
    const collection = ld.find((j) => j["@type"] === "CollectionPage");
    expect(collection.hasPart.map((p: { url: string }) => p.url)).toContain(`${SITE_URL}/reference/density_screen.html`);
    expect(JSON.stringify(ld).toLowerCase()).not.toMatch(/aggregaterating|"review"|ratingvalue/);
  });
});

describe("the reference page needs React only to render", () => {
  it("is a server component", () => {
    expect(React.isValidElement(React.createElement("div"))).toBe(true);
  });
});
